function d_kbquery(P,R){var docs=P.docs||[];var q=(P.query||'').toLowerCase().split(/\s+/);var sc=docs.map(function(d){var t=(d.title+' '+d.text).toLowerCase();var hit=q.filter(function(w){return w&&t.indexOf(w)>=0;}).length;return{id:d.id,title:d.title,score:+(hit/Math.max(1,q.length)).toFixed(2)};});sc.sort(function(a,b){return b.score-a.score;});return{query:P.query,matches:sc.filter(function(s){return s.score>0;}).length,top:sc.slice(0,3)};}

